<template>
  <div class="app-container">
    <el-form inline @submit.prevent="search"><el-form-item label="标题前缀"><el-input v-model="query.title" maxlength="120" clearable @keyup.enter="search"/></el-form-item><el-form-item label="状态"><el-select v-model="query.published" clearable style="width:130px"><el-option :value="0" label="未发布"/><el-option :value="1" label="已发布"/></el-select></el-form-item><el-form-item><el-button type="primary" @click="search">搜索</el-button><el-button @click="reset">重置</el-button></el-form-item></el-form>
    <el-row style="margin-bottom:12px;gap:10px"><el-button v-if="allowed('publish')" :disabled="!selected.length||busy" @click="batch('publish')">批量发布</el-button><el-button v-if="allowed('publish')" :disabled="!selected.length||busy" @click="batch('unpublish')">批量下架</el-button><el-button v-hasPermi="[perm+'add']" type="primary" plain @click="create">新增{{ label }}</el-button></el-row>
    <el-alert title="保存只更新草稿；点击发布才替换线上内容。首次发布后访问地址锁定。" type="info" :closable="false" style="margin-bottom:12px"/>
    <el-table :data="rows" v-loading="loading" @selection-change="selected=$event"><el-table-column v-if="allowed('publish')" type="selection" width="45"/><el-table-column prop="title" label="草稿标题" min-width="180" show-overflow-tooltip/><el-table-column prop="slug" label="访问地址" min-width="150" show-overflow-tooltip/><el-table-column label="状态" width="150"><template #default="s"><el-tag :type="s.row.isPublished ? 'success' : 'info'">{{ s.row.isPublished ? '已发布' : '未发布' }}</el-tag><el-tag v-if="s.row.isPublished && s.row.workingRevisionId !== s.row.publishedRevisionId" type="warning">有新稿</el-tag></template></el-table-column><el-table-column prop="revisionSeq" label="修订" width="70"/><el-table-column prop="publishedAt" label="最近发布" width="165"/><el-table-column label="操作" min-width="330"><template #default="s"><el-button v-if="allowed('query') && allowed('edit')" link type="primary" @click="edit(s.row)">编辑</el-button><el-button v-if="allowed('query')" link type="primary" @click="check(s.row)">发布前检查</el-button><el-button v-if="allowed('query')" link type="primary" @click="preview(s.row)">草稿预览</el-button><el-button v-if="allowed('query')" link type="primary" @click="history(s.row)">历史</el-button><el-button v-if="allowed('query')" link type="primary" @click="schedule.open(s.row)">定时任务</el-button><el-button v-if="allowed('publish')" link type="success" @click="change(s.row, 'publish')">发布</el-button><el-button v-if="allowed('publish') && s.row.isPublished" link type="warning" @click="change(s.row,'unpublish')">下架</el-button><el-button v-if="s.row.isPublished" link type="primary" @click="online(s.row)">查看线上</el-button><el-button v-if="allowed('remove')" link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table>
    <pagination v-show="total > 0" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="load"/>
    <OperationsReport ref="operationsReport"/>
    <ContentSchedule ref="schedule" :kind="kind" @changed="load"/>
    <el-dialog v-model="editing" :title="(form.contentId ? '编辑' : '新增') + label + '草稿'" width="min(1000px, calc(100vw - 32px))" append-to-body :close-on-click-modal="false" destroy-on-close>
      <el-form ref="formRef" :model="form" :rules="rules" label-width="95px">
        <el-row :gutter="16"><el-col :span="14"><el-form-item label="标题" prop="title"><el-input v-model="form.title" maxlength="120" show-word-limit/></el-form-item></el-col><el-col :span="10"><el-form-item label="访问地址" prop="slug"><el-input v-model="form.slug" :disabled="lockedSlug" maxlength="80" placeholder="例如 company-news"/></el-form-item></el-col></el-row>
        <el-form-item v-if="kind!=='page'" :label="kind==='product'?'产品栏目':'文章栏目'" prop="channelId"><el-select v-model="form.channelId" filterable remote :remote-method="channels" @visible-change="v=>v && channels('')" placeholder="输入栏目名称搜索" style="width:100%"><el-option v-for="r in options" :key="r.channelId" :value="r.channelId" :label="r.name + (r.status==='0'?'':'（停用）')"/></el-select></el-form-item>
        <el-form-item v-if="kind==='product'" label="产品编号"><el-input v-model="form.productCode" maxlength="80"/></el-form-item><el-form-item v-if="kind==='product'" label="产品参数"><el-input v-model="form.productParams" type="textarea" :rows="3" maxlength="2000" placeholder="每行一个参数，例如：材质：不锈钢"/></el-form-item><el-form-item v-if="kind==='product'" label="产品图集"><AssetPicker v-model="galleryPick"/><el-button :disabled="!galleryPick || (form.galleryIds?.length || 0)>=16" @click="addGallery">加入图集</el-button><el-tag v-for="id in form.galleryIds" :key="id" closable @close="form.galleryIds=form.galleryIds.filter(x=>x!==id)">素材 #{{id}}</el-tag></el-form-item><el-form-item label="摘要"><el-input v-model="form.summary" type="textarea" :rows="2" maxlength="500" show-word-limit/></el-form-item>
        <el-form-item label="正文" prop="bodyHtml"><CMSRichEditor v-if="editing" ref="editor" v-model="form.bodyHtml"/></el-form-item>
        <el-form-item label="封面"><AssetPicker v-model="form.coverAssetId"/></el-form-item>
        <el-row :gutter="16"><el-col :span="12"><el-form-item label="作者"><el-input v-model="form.author" maxlength="60"/></el-form-item></el-col><el-col :span="12"><el-form-item label="封面说明"><el-input v-model="form.coverAltText" maxlength="200"/></el-form-item></el-col></el-row>
        <el-form-item label="SEO标题"><el-input v-model="form.seoTitle" maxlength="150"/></el-form-item><el-form-item label="SEO描述"><el-input v-model="form.seoDescription" maxlength="300"/></el-form-item><el-form-item label="修订备注"><el-input v-model="form.remark" maxlength="500"/></el-form-item>
      </el-form><template #footer><el-button @click="editing=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存草稿</el-button></template>
    </el-dialog>
    <el-dialog v-model="historyOpen" title="不可变历史版本（恢复只创建新草稿）" width="min(850px, calc(100vw - 32px))" append-to-body><el-table :data="revisions"><el-table-column prop="revisionNo" label="版本" width="70"/><el-table-column prop="title" label="标题" min-width="160"/><el-table-column prop="createBy" label="保存人" width="110"/><el-table-column prop="createTime" label="时间" width="165"/><el-table-column prop="remark" label="备注" min-width="100"/><el-table-column label="操作" width="110"><template #default="s"><el-button v-if="allowed('edit')" link type="primary" @click="restore(s.row)">恢复为草稿</el-button></template></el-table-column></el-table><pagination v-show="historyTotal > 0" :total="historyTotal" v-model:page="historyQuery.pageNum" v-model:limit="historyQuery.pageSize" @pagination="loadHistory"/></el-dialog>
    <el-dialog v-model="previewOpen" title="草稿预览 · 仅后台可见" width="min(1000px, calc(100vw - 32px))" append-to-body destroy-on-close @closed="releasePreview"><iframe v-if="previewHTML" :srcdoc="previewHTML" sandbox="" referrerpolicy="no-referrer" title="草稿预览" style="border:0;width:100%;height:65vh"/></el-dialog>
  </div>
</template>
<script setup>
import { ref, reactive, computed, onMounted, onBeforeUnmount, onDeactivated } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import auth from '@/plugins/auth'
import { listContent, getContent, saveContent, contentAction, contentHistory, listChannels, privateImage } from '@/api/cms/content'
import CMSRichEditor from './CMSRichEditor.vue'
import AssetPicker from './AssetPicker.vue'
import OperationsReport from './OperationsReport.vue'
import ContentSchedule from './ContentSchedule.vue'
import request from '@/utils/request'
const props = defineProps({ kind: { type: String, required: true } })
const perm = computed(()=>'cms:'+props.kind+':'), label = computed(()=>props.kind==='article'?'文章':props.kind==='product'?'产品':'单页')
const allowed = action => auth.hasPermi(perm.value+action)
let opsEpoch=0;
const selected=ref([]),operationsReport=ref(),schedule=ref();
async function check(row){const ticket=++opsEpoch;const r=await request({url:`/cms/${props.kind}/${row.contentId}/check`});if(ticket!==opsEpoch||!operationsReport.value)return;operationsReport.value.open('发布前检查',r.data.issues,r.data.ready?'发布条件检查通过；发布仍会重验版本，正文链接请另用站点巡检':'存在阻止发布的问题，请修复后再试')}
async function batch(action){if(busy.value)return;if(selected.value.length>20){ElMessage.warning('每次最多选择20项');return};const ticket=++opsEpoch;const items=selected.value.map(r=>({contentId:r.contentId,version:r.version}));try{await ElMessageBox.confirm(`确认对${items.length}项执行${action==='publish'?'发布':'下架'}？每项独立执行，可能部分成功。`,'批量确认');busy.value=true;const r=await request({url:`/cms/${props.kind}/batch`,method:'post',data:{action,items},timeout:60000});if(ticket!==opsEpoch||!operationsReport.value)return;operationsReport.value.open('批量操作结果',r.data.results.map(x=>({...x,code:x.success?'SUCCESS':'FAILED'})),`成功 ${r.data.successCount} 项，失败 ${r.data.failureCount} 项`);await load()}catch{}finally{busy.value=false}}
const galleryPick=ref(0);function addGallery(){form.galleryIds=[...new Set([...(form.galleryIds||[]),galleryPick.value])];galleryPick.value=0}
const rows=ref([]),total=ref(0),loading=ref(false),busy=ref(false),editing=ref(false),lockedSlug=ref(false),formRef=ref(),editor=ref(),options=ref([])
const query=reactive({title:'',published:undefined,pageNum:1,pageSize:10}), form=reactive({})
const rules={title:[{required:true,message:'请输入标题',trigger:'blur'}],slug:[{required:true,pattern:/^[a-z][a-z0-9-]{0,79}$/,message:'小写字母开头，支持数字和连字符',trigger:'blur'}],channelId:[{type:'number',min:1,required:true,message:'请选择文章栏目',trigger:'change'}],bodyHtml:[{required:true,message:'请输入正文',trigger:'blur'}]}
let epoch=0, editEpoch=0, channelEpoch=0, previewEpoch=0, historyEpoch=0
async function load(){const ticket=++epoch;loading.value=true;try{const r=await listContent(props.kind,{...query,published:query.published===''?undefined:query.published});if(ticket===epoch){rows.value=r.rows;total.value=r.total;selected.value=[]}}finally{if(ticket===epoch)loading.value=false}}
function search(){query.pageNum=1;load()} function reset(){query.title='';query.published=undefined;search()}
function blank(){return {productCode:'',productParams:'',galleryIds:[],contentId:0,version:0,title:'',slug:'',channelId:0,summary:'',bodyHtml:'',author:'',coverAssetId:0,coverAltText:'',seoTitle:'',seoDescription:'',remark:''}}
function create(){++editEpoch;Object.assign(form,blank());lockedSlug.value=false;editing.value=true;options.value=[]}
async function edit(row){const ticket=++editEpoch;const d=(await getContent(props.kind,row.contentId)).data;if(ticket!==editEpoch)return;Object.assign(form,blank(),d.draft,{contentId:d.contentId,version:d.version,slug:d.slug,channelId:d.draft.channelId||0,coverAssetId:d.draft.coverAssetId||0});lockedSlug.value=!!d.everPublished;if(form.channelId)options.value=[{channelId:form.channelId,name:'当前栏目 #'+form.channelId,status:'0'}];editing.value=true}
async function channels(name){const ticket=++channelEpoch;const r=await listChannels({kind:props.kind==='product'?'PRODUCT':'ARTICLE',name,pageNum:1,pageSize:50});if(ticket===channelEpoch)options.value=r.rows}
async function save(){if(busy.value||!editor.value?.ready())return;await formRef.value.validate();busy.value=true;try{await saveContent(props.kind,{...form,channelId:props.kind==='page'?0:form.channelId});editing.value=false;ElMessage.success('草稿已保存，线上版本未改变');await load()}finally{busy.value=false}}
async function change(row,action){if(busy.value)return;try{await ElMessageBox.confirm(action==='publish'?'将当前草稿发布到公开网站？':'下架后访客将无法访问，历史版本继续保留。',action==='publish'?'发布确认':'下架确认',{type:'warning'});busy.value=true;await contentAction(props.kind,row.contentId,action,{version:row.version});ElMessage.success('操作成功');await load()}catch(e){if(e!=='cancel'&&e!=='close')console.warn('内容操作未完成')}finally{busy.value=false}}
async function remove(row){try{await ElMessageBox.confirm('删除后停止公开，保留历史修订与素材引用；访问地址继续保留。','删除确认',{type:'warning'});await contentAction(props.kind,row.contentId,'remove',{version:row.version});await load()}catch{}}
function online(row){window.open((props.kind==='article'?'/news/':props.kind==='product'?'/products/':'/p/')+encodeURIComponent(row.slug),'_blank','noopener,noreferrer')}
const historyOpen=ref(false),revisions=ref([]),historyTotal=ref(0),historyOwner=ref(null),historyQuery=reactive({pageNum:1,pageSize:10})
async function history(row){historyOwner.value=row;historyQuery.pageNum=1;historyOpen.value=true;await loadHistory()}
async function loadHistory(){const ticket=++historyEpoch;const r=await contentHistory(props.kind,historyOwner.value.contentId,{...historyQuery});if(ticket===historyEpoch&&historyOpen.value){revisions.value=r.rows;historyTotal.value=r.total}}
async function restore(revision){if(busy.value)return;try{await ElMessageBox.confirm('复制此版本为新草稿，线上内容保持不变？','恢复草稿');busy.value=true;await contentAction(props.kind,historyOwner.value.contentId,'restore',{version:historyOwner.value.version,revisionId:revision.revisionId});historyOpen.value=false;ElMessage.success('已恢复为新草稿，尚未发布');await load()}catch{}finally{busy.value=false}}
const previewOpen=ref(false),previewHTML=ref('');const previewURLs=[]
function releasePreview(){++previewEpoch;for(const u of previewURLs)URL.revokeObjectURL(u);previewURLs.length=0;previewHTML.value=''}
async function preview(row){releasePreview();const ticket=previewEpoch;const d=(await getContent(props.kind,row.contentId)).data.draft;if(ticket!==previewEpoch)return;const doc=new DOMParser().parseFromString(d.bodyHtml,'text/html');if(props.kind==='product'){const code=doc.createElement('p');code.textContent=d.productCode?'产品编号：'+d.productCode:'';doc.body.prepend(code);const params=doc.createElement('pre');params.textContent=d.productParams||'';doc.body.append(params);for(const id of d.galleryIds||[]){const img=doc.createElement('img');img.setAttribute('src','/media/'+id);img.alt='产品图集';doc.body.append(img)}};for(const img of doc.querySelectorAll('img')){const m=/^\/media\/([1-9][0-9]*)$/.exec(img.getAttribute('src')||'');if(!m||!auth.hasPermi('cms:asset:query')){img.replaceWith(doc.createTextNode('[图片需素材查询权限]'));continue};try{const blob=await privateImage(Number(m[1]));if(ticket!==previewEpoch)return;const u=URL.createObjectURL(blob);previewURLs.push(u);img.src=u}catch{img.remove()}}if(ticket!==previewEpoch)return;const title=doc.createElement('h1');title.textContent=d.title;doc.body.prepend(title);previewHTML.value='<!doctype html><html><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; img-src blob:; style-src \'unsafe-inline\'; base-uri \'none\'"><style>body{font:16px/1.8 sans-serif;padding:20px;color:#222}img{max-width:100%}</style></head><body>'+doc.body.innerHTML+'</body></html>';previewOpen.value=true}
function cleanup(){schedule.value?.close();++opsEpoch;operationsReport.value?.close();++epoch;++editEpoch;++channelEpoch;++historyEpoch;editing.value=false;historyOpen.value=false;previewOpen.value=false;releasePreview()}
onMounted(load);onDeactivated(cleanup);onBeforeUnmount(cleanup)
</script>
